module rebus_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] num_positive,\n    input wire [3:0] num_negative,\n    input wire [19:0] n,\n    output reg done,\n    output reg possible,\n    output reg [19:0] positive_terms [0:7],\n    output reg [19:0] negative_terms [0:7]\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PRECOMPUTE = 3'd1;\n    localparam [2:0] CHECK = 3'd2;\n    localparam [2:0] ASSIGN_POSITIVE = 3'd3;\n    localparam [2:0] ASSIGN_NEGATIVE = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg signed [31:0] adjustment;\n    reg [31:0] rem;\n    reg [3:0] index;\n    reg [31:0] limit_positive;\n    reg [31:0] limit_negative;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            possible <= 1'b0;\n            adjustment <= 32'd0;\n            rem <= 32'd0;\n            index <= 4'd0;\n            limit_positive <= 32'd0;\n            limit_negative <= 32'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                positive_terms[i] <= 20'd1;\n                negative_terms[i] <= 20'd1;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    possible <= 1'b0;\n                    index <= 4'd0;\n                    if (start) state <= PRECOMPUTE;\n                end\n\n                PRECOMPUTE: begin\n                    adjustment <= n - (num_positive - num_negative);\n                    limit_positive <= num_positive * (n - 20'd1);\n                    limit_negative <= num_negative * (n - 20'd1);\n                    state <= CHECK;\n                end\n\n                CHECK: begin\n                    if (adjustment >= 0) begin\n                        if (adjustment <= limit_positive) begin\n                            possible <= 1'b1;\n                            rem <= adjustment;\n                            state <= ASSIGN_POSITIVE;\n                        end else begin\n                            possible <= 1'b0;\n                            state <= DONE_STATE;\n                        end\n                    end else begin\n                        if (-adjustment <= limit_negative) begin\n                            possible <= 1'b1;\n                            rem <= -adjustment;\n                            state <= ASSIGN_NEGATIVE;\n                        end else begin\n                            possible <= 1'b0;\n                            state <= DONE_STATE;\n                        end\n                    end\n                end\n\n                ASSIGN_POSITIVE: begin\n                    if (index < num_positive) begin\n                        if (rem > (n - 20'd1)) begin\n                            positive_terms[index] <= 20'd1 + (n - 20'd1);\n                            rem <= rem - (n - 20'd1);\n                        end else begin\n                            positive_terms[index] <= 20'd1 + rem[19:0];\n                            rem <= 32'd0;\n                        end\n                        index <= index + 4'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                ASSIGN_NEGATIVE: begin\n                    if (index < num_negative) begin\n                        if (rem > (n - 20'd1)) begin\n                            negative_terms[index] <= 20'd1 + (n - 20'd1);\n                            rem <= rem - (n - 20'd1);\n                        end else begin\n                            negative_terms[index] <= 20'd1 + rem[19:0];\n                            rem <= 32'd0;\n                        end\n                        index <= index + 4'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule